 $('#bay').onchange=e=>moveItem(a.id,{bay:+e.target.value});$('#height').onchange=e=>moveItem(a.id,{y:Number(e.target.value)/1000});$('#heightSlider').oninput=e=>{$('#height').value=e.target.value;};$('#heightSlider').onchange=e=>moveItem(a.id,{y:+e.target.value/1000});$$('[data-color]').forEach(b=>b.onclick=()=>{a.color=b.dataset.color;changed();rebuild(a);detail();});if($('#toggleState'))$('#toggleState').onclick=()=>{const test={...a,state:a.state?0:1};if(conflict(test,items)){toast('切换后会与相邻模块重叠，请先调整位置');return;}a.state=test.state;changed();detail();};if($('#intensity'))$('#intensity').oninput=e=>{a.intensity=+e.target.value;$('#intensityValue').textContent=a.intensity+'%';changed();};if($('#temperature'))$('#temperature').onchange=e=>{a.temperature=+e.target.value;changed();};$('#remove').onclick=()=>{const g=models.get(a.id);dispose(g);models.delete(a.id);items=items.filter(x=>x.id!==a.id);selected=null;changed();detail();updateSelection();};$('#duplicate').onclick=()=>addItem(a.type,a.bay,a.y+.3,a);
