function changed(){dirty=true;$('#sceneTitle').textContent=PRESETS[preset].name+' · 自定义';stopPlay();}
function select(id){selected=id;rightTab='detail';detail();updateSelection();}
function moveItem(id,patch){const a=items.find(x=>x.id===id);if(!a)return;if(patch.y!==undefined&&!Number.isFinite(patch.y)){toast('请输入有效高度');detail();return;}const next=clampPosition({...a,...patch});if(conflict(next,items)){toast('这个位置与其他模块重叠，请换一档或一个分区');detail();return;}Object.assign(a,next);changed();detail();}
function addItem(type,bay=0,y=1.4,from=null){if(!M[type])return;const free=findSpace(type,items,bay,y);if(!free){toast('墙面暂时没有足够空间，请先移除或移动模块');return;}const a={...(from?clone(from):free),...free,id:'u'+uid++};items.push(a);buildModule(a);changed();select(a.id);toast('已添加'+M[type].name+'，可拖动调整');}
function exportConfig(){const d={project:'邮轮72变',version:'concept-1',wall_mm:[2900,2900],rail_spacing_mm:714,rung_pitch_mm:25,scene:PRESETS[preset].name,modified:dirty,warning:'新增模块尺寸为概念值。25mm节距待实测；挂接结构、承重与供电未验证。',modules:items.map(a=>({...a,name:M[a.type].name,height_mm:Math.round(a.y*1000),dimensions_mm:[M[a.type].w,M[a.type].h,M[a.type].d].map(v=>Math.round(v*1000)),interface:M[a.type].anchor,standard_parts:M[a.type].parts}))};const url=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));download(url,'邮轮72变_模块配置.json');setTimeout(()=>URL.revokeObjectURL(url),1000);toast('方案与模块清单已导出');}
