const silver=mat('#aeb8c6',.5),orange=mat('#ed8e40'),dark=mat('#343e4e'),white=mat('#edece7'),glass=new THREE.MeshPhysicalMaterial({color:'#b9d2df',transparent:true,opacity:.23,roughness:.12,metalness:.12,depthWrite:false,side:THREE.DoubleSide});
function cube(g,w,h,d,x,y,z,m){const q=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);q.position.set(x,y,z);q.castShadow=true;q.receiveShadow=true;g.add(q);return q;}
function cylinder(g,r,h,x,y,z,m,axis='y'){const q=new THREE.Mesh(new THREE.CylinderGeometry(r,r,h,20),m);q.position.set(x,y,z);if(axis==='x')q.rotation.z=Math.PI/2;if(axis==='z')q.rotation.x=Math.PI/2;q.castShadow=true;g.add(q);return q;}
function textTexture(top,bottom,bg='#eee9db'){const c=document.createElement('canvas');c.width=768;c.height=512;const ctx=c.getContext('2d');ctx.fillStyle=bg;ctx.fillRect(0,0,768,512);ctx.fillStyle='#3158e8';ctx.fillRect(52,50,70,8);ctx.font='600 48px sans-serif';ctx.fillText(top,52,160);ctx.font='24px sans-serif';ctx.fillStyle='#627086';ctx.fillText(bottom,52,216);ctx.font='bold 135px sans-serif';ctx.fillStyle='#3158e8';ctx.fillText('72+',460,444);ctx.strokeStyle='#c8cbd1';ctx.beginPath();ctx.moveTo(52,300);ctx.lineTo(714,300);ctx.stroke();const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return new THREE.MeshStandardMaterial({map:t,roughness:.8});}
function node(g,x,y,co){const b=mat(co);cube(g,.048,.048,.0055,x,y,.04375,b);cube(g,.002,.048,.031,x-.023,y,.0185,b);cube(g,.002,.048,.031,x+.023,y,.0185,b);cube(g,.044,.044,.007,x,y,.0305,b);for(const dx of [-.017,.017])cylinder(g,.003,.030,x+dx,y,.026,silver,'z');}
function bracket(g,h,co){for(const x of [-BAY/2,BAY/2])for(const y of [-h/2,h/2])node(g,x,y,co);for(const y of [-h/2,h/2])cube(g,BAY,.022,.015,0,y,.033,dark);}
function buildModule(a,enter=false){if(!scene)return;const m=M[a.type],g=new THREE.Group(),colored=mat(a.color);g.userData.id=a.id;g.position.set(CENTERS[a.bay],a.y,enter?-.12:0);g.userData.targetZ=0;let act=null;
 if(m.mount===2){for(const y of [-.05,.05])node(g,-BAY/2,y,a.color);}else bracket(g,a.type==='panel'?.575:a.type==='acoustic'?.65:a.type==='worktop'?.15:a.type==='shelf'?.2:.4,a.color);
 if(a.type==='panel'){const p=cube(g,.700,.550,.006,0,0,.037,white);const front=new THREE.Mesh(new THREE.PlaneGeometry(.700,.550),textTexture('ON THE OCEAN','A journey in collected stories'));front.position.set(0,0,.0401);g.add(front);}
 if(a.type==='cabinet'){const z=.05;cube(g,.66,.018,.28,0,-.25,z+.14,colored);cube(g,.66,.018,.28,0,.25,z+.14,colored);for(const x of [-.321,.321])cube(g,.018,.5,.28,x,0,z+.14,colored);cube(g,.66,.5,.01,0,0,z,white);cube(g,.62,.008,.24,0,-.04,z+.13,glass);cube(g,.12,.045,.12,-.15,-.215,z+.13,white);cylinder(g,.035,.09,-.15,-.148,z+.13,orange);cube(g,.11,.13,.08,.14,.033,z+.12,white);act=new THREE.Group();act.position.set(-.325,0,z+.28);cube(act,.65,.49,.008,.325,0,0,glass);cube(act,.009,.09,.012,.6,0,.009,silver);g.add(act);}
 if(a.type==='shelf'){cube(g,.66,.022,.28,0,0,.185,colored);cube(g,.66,.026,.01,0,.024,.321,colored);for(const x of [-.28,.28]){const b=cube(g,.018,.24,.02,x,-.08,.13,silver);b.rotation.x=-.85;}for(let i=0;i<3;i++)cube(g,.085,.014,.15,-.16+i*.09,.025,.19,i===1?orange:white);}
 if(a.type==='lamp'){const x=-BAY/2;cylinder(g,.012,.1,x,0,.09,silver,'z');const hinge=new THREE.Group();hinge.position.set(x,0,.16);hinge.rotation.x=Math.PI/4;cylinder(hinge,.045,.09,0,0,0,colored,'z');const disk=cylinder(hinge,.038,.004,0,0,.047,new THREE.MeshStandardMaterial({color:'#fff4d0',emissive:'#ffd08a',emissiveIntensity:1}),'z');g.add(hinge);const light=new THREE.SpotLight('#ffd08a',0,2.8,.6,.8,1.4);light.position.set(x,-.02,.18);light.target.position.set(x,-.65,.03);g.add(light,light.target);g.userData.light=light;g.userData.disk=disk;}
 if(a.type==='scent'){const x=-BAY/2;cube(g,.12,.22,.13,x,0,.105,colored);cube(g,.086,.125,.007,x,-.025,.174,white);for(let i=0;i<5;i++)cube(g,.065,.003,.002,x,.058+i*.008,.172,dark);g.userData.particles=[];const particleMat=new THREE.MeshBasicMaterial({color:'#78c5cd',transparent:true,opacity:.5});for(let i=0;i<10;i++){const p=new THREE.Mesh(new THREE.SphereGeometry(.003,6,6),particleMat);g.add(p);g.userData.particles.push(p);}}
 if(a.type==='sign'){const x=-BAY/2;cube(g,.30,.18,.025,x,0,.06,colored);const f=new THREE.Mesh(new THREE.PlaneGeometry(.285,.165),textTexture('WELCOME','72+ / Explore & connect','#fafafa'));f.position.set(x,0,.074);g.add(f);}
 if(a.type==='worktop'){act=new THREE.Group();act.position.set(0,0,.05);cube(act,.65,.025,.42,0,0,.21,colored);cube(act,.65,.012,.008,0,.018,.416,colored);for(const x of [-.26,.26]){const b=cube(act,.016,.32,.018,x,-.11,.16,silver);b.rotation.x=-.85;}g.add(act);}
 if(a.type==='acoustic'){cube(g,.65,.7,.045,0,0,.065,mat('#829f9e'));for(let i=0;i<8;i++)cube(g,.002,.68,.002,-.285+i*.08,0,.089,mat('#748f90'));}
 g.userData.act=act;g.userData.state=a.state;g.traverse(o=>{if(o.isMesh)o.userData.itemId=a.id;});scene.add(g);models.set(a.id,g);return g;}
function dispose(g){if(!g)return;scene.remove(g);g.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material&&!Object.values({silver,orange,dark,white,glass}).includes(o.material)){o.material.map?.dispose();o.material.dispose();}});}
