function updateSelection(){if(!selectionBox)return;const g=models.get(selected);selectionBox.visible=!!g;if(g)selectionBox.box.setFromObject(g);}
function dimensions(){const g=new THREE.Group();const material=new THREE.LineBasicMaterial({color:'#71809a'});for(const [a,b] of [[[-1.45,.13,.07],[1.45,.13,.07]],[[-1.5,0,.07],[-1.5,2.9,.07]]]){const geom=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(...a),new THREE.Vector3(...b)]);g.add(new THREE.Line(geom,material));}g.visible=false;scene.add(g);return g;}
function init3D(){scene=new THREE.Scene();scene.background=new THREE.Color('#f0f2f5');renderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;stage.prepend(renderer.domElement);camera=new THREE.PerspectiveCamera(40,1,.01,80);orbit=new OrbitControls(camera,renderer.domElement);orbit.enableDamping=true;orbit.minDistance=1.8;orbit.maxDistance=8;orbit.maxPolarAngle=Math.PI/2+.08;orbit.minAzimuthAngle=-Math.PI/2.5;orbit.maxAzimuthAngle=Math.PI/2.5;orbit.target.set(0,1.35,0);camera.position.set(3.7,2.4,5.8);orbit.update();ambient=new THREE.HemisphereLight('#ffffff','#798192',2.5);scene.add(ambient);sun=new THREE.DirectionalLight('#fff7e9',3);sun.position.set(-3,5,5);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-3;sun.shadow.camera.right=3;sun.shadow.camera.top=4;sun.shadow.camera.bottom=-1;sun.shadow.normalBias=.008;scene.add(sun);wallMat=mat('#f5f4ef');floorMat=mat('#d9dde3');cube(scene,2.9,2.9,.10,0,1.45,-.05,wallMat);cube(scene,9,.04,6,0,-.022,1.3,floorMat);const rails=[-1.071,-.357,.357,1.071];for(const x of rails){cube(scene,.0164,2.45,.0017,x,1.425,.00085,silver);for(const s of [-1,1]){cube(scene,.002,2.45,.021,x+s*.0072,1.425,.0122,silver);cube(scene,.0052,2.45,.0013,x+s*.0084,1.425,.02335,silver);}for(let y=.2125;y<2.65;y+=PITCH)cylinder(scene,.0025,.0124,x,y,.017,silver,'x');}
 dimensionGroup=dimensions();selectionBox=new THREE.Box3Helper(new THREE.Box3(),0x3158e8);selectionBox.material.depthTest=false;selectionBox.material.transparent=true;selectionBox.material.opacity=.6;scene.add(selectionBox);for(const a of items)buildModule(a);new ResizeObserver(resize).observe(stage);resize();setupPointer();animate();}
function resize(){if(!renderer)return;const w=stage.clientWidth,h=stage.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();}
function setView(v){if(!orbit)return;view=v;$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));orbit.enableRotate=v==='3d';orbit.target.set(0,1.4,0);camera.position.set(v==='front'?0:3.7,v==='front'?1.4:2.4,v==='front'?6.1:5.8);orbit.update();}
function animate(){requestAnimationFrame(animate);const t=clock.getElapsedTime();for(const a of items){const g=models.get(a.id);if(!g)continue;g.position.x=THREE.MathUtils.lerp(g.position.x,CENTERS[a.bay],.15);g.position.y=THREE.MathUtils.lerp(g.position.y,a.y,.15);g.position.z=THREE.MathUtils.lerp(g.position.z,0,.1);const act=g.userData.act;if(act){if(a.type==='cabinet')act.rotation.y=THREE.MathUtils.lerp(act.rotation.y,a.state?-Math.PI*.62:0,.12);if(a.type==='worktop')act.rotation.x=THREE.MathUtils.lerp(act.rotation.x,a.state?0:-Math.PI/2,.12);}if(g.userData.light){const l=g.userData.light;l.intensity=THREE.MathUtils.lerp(l.intensity,a.state?a.intensity*.017:0,.1);const color=a.temperature===2700?'#ffbd67':a.temperature===3200?'#ffd794':'#fff0d2';l.color.set(color);g.userData.disk.material.emissive.set(color);g.userData.disk.material.emissiveIntensity=a.state?a.intensity/55:0;}if(g.userData.particles){g.userData.particles.forEach((p,i)=>{p.visible=!!a.state;const ph=(t*.3+i/10)%1;p.position.set(-BAY/2+Math.sin(t+i)*.013,.10+ph*.18,.18+ph*.05);});}}
 ambient.intensity=THREE.MathUtils.lerp(ambient.intensity,night?.52:2.5,.04);sun.intensity=THREE.MathUtils.lerp(sun.intensity,night?.28:3,.04);const bg=new THREE.Color(night?'#6b768b':'#f0f2f5');scene.background.lerp(bg,.04);orbit.update();updateSelection();renderer.render(scene,camera);}
function setupPointer(){const canvas=renderer.domElement,ray=new THREE.Raycaster(),ndc=new THREE.Vector2(),plane=new THREE.Plane(new THREE.Vector3(0,0,1),-.05);let drag=null;
 const get=e=>{const r=canvas.getBoundingClientRect();ndc.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(ndc,camera);};
 const point=e=>{get(e);return ray.ray.intersectPlane(plane,new THREE.Vector3());};
 canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;get(e);const hits=ray.intersectObjects([...models.values()],true);if(!hits.length)return;const id=hits[0].object.userData.itemId,a=items.find(x=>x.id===id);if(!a)return;select(id);const start=point(e);if(!start)return;drag={id,start,a:{...a},px:e.clientX,py:e.clientY,moved:false};orbit.enabled=false;canvas.setPointerCapture(e.pointerId);});
 canvas.addEventListener('pointermove',e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.px,e.clientY-drag.py)<5)return;drag.moved=true;const p=point(e);if(!p)return;const bay=Math.round((CENTERS[drag.a.bay]+p.x-drag.start.x)/BAY)+1;const a=items.find(x=>x.id===drag.id),test=clampPosition({...a,bay,y:drag.a.y+p.y-drag.start.y});if(!conflict(test,items))Object.assign(a,test);});
 const release=()=>{if(drag?.moved){changed();detail();}drag=null;orbit.enabled=true;};canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
 stage.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='copy';};stage.ondrop=e=>{e.preventDefault();const type=e.dataTransfer.getData('text/plain');if(!M[type])return;const p=point(e);if(!p)return;const bay=Math.max(0,Math.min(2,Math.round((p.x+(M[type].mount===2?BAY/2:0))/BAY)+1));addItem(type,bay,p.y);};
}
$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));catalog();});$$('[data-tab]').forEach(b=>b.onclick=()=>{rightTab=b.dataset.tab;detail();});$$('[data-scene]').forEach(b=>b.onclick=()=>{stopPlay();setPreset(+b.dataset.scene);});$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#resetView').onclick=()=>setView(view);$('#dims').onclick=()=>{showDims=!showDims;if(dimensionGroup)dimensionGroup.visible=showDims;$('#dims').setAttribute('aria-pressed',String(showDims));$('#dimText').textContent=showDims?'48 mm 节点 / 22 mm 梯柱 / 25 mm 节距（假设）':'节点 48 mm · 柱距 714 mm';};$('#play').onclick=()=>{if(playing){stopPlay();return;}playing=true;$('#play').textContent='Ⅱ 暂停演示';timer=setInterval(()=>setPreset((preset+1)%PRESETS.length),6500);};$('#export').onclick=exportConfig;$('#snapshot').onclick=()=>{if(!renderer){toast('当前无法生成三维截图');return;}renderer.render(scene,camera);download(renderer.domElement.toDataURL('image/png'),'邮轮72变_当前配置.png');toast('当前三维画面已保存');};$('#about').onclick=()=>$('#aboutModal').showModal();$('#closeAbout').onclick=()=>$('#aboutModal').close();$('#aboutModal').onclick=e=>{if(e.target===$('#aboutModal'))$('#aboutModal').close();};window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||$('#aboutModal').open)return;const a=items.find(x=>x.id===selected);if(!a)return;if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();moveItem(a.id,{y:a.y+(e.key==='ArrowUp'?PITCH:-PITCH)});}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();$('#remove')?.click();}});
catalog();detail();try{init3D();}catch(e){$('#loaderror').hidden=false;$('#loaderror').textContent='三维画面暂时无法启动。请使用支持 WebGL 的新版浏览器并开启图形加速。仍可通过模块库、设置和清单查看方案。';console.error(e);}
